lab=[r for r in load_lab() if r['family']=='bigram_lm' and r['model_type']=='transformer_lm' and not r.get('excluded') and np.isfinite(r['mean'])]
g=collections.defaultdict(list)
for r in lab:g[r['set_id']].append(r)
pairs=[]
for sid,rows in g.items():
 for i,a in enumerate(rows):
  for b in rows[i+1:]:
   if a['optimizer']!=b['optimizer'] or a['loss']!=b['loss']:continue
   diff=[k for k in ['d_model','num_layers','num_heads','d_ff'] if a[k]!=b[k]]
   if len(diff)!=1 or diff[0] not in ['num_heads','d_ff']:continue
   k=diff[0]; lo,hi=sorted([a,b],key=lambda r:r[k]);pairs.append((k,lo,hi))
print('pairs',len(pairs))
for k in ['num_heads','d_ff']:
 for band in ['<.01','.01-.1','>=.1']:
  ps=[(a,b) for kk,a,b in pairs if kk==k and ((a['optimizer']['lr']*a['budget']['training_steps']<.01) if band=='<.01' else (.01<=a['optimizer']['lr']*a['budget']['training_steps']<.1) if band=='.01-.1' else a['optimizer']['lr']*a['budget']['training_steps']>=.1)]
