 chunks=re.split(r'### Choice ([A-E])',r['question']); cs=[]
 for i in range(1,len(chunks),2):
  s=chunks[i+1]
  def get(p):
   m=re.search(p,s);return m.group(1) if m else '?'
  if get(r'- Type: ([^\n]+)')!='causal transformer LM':continue
  cs.append({'l':chunks[i],'d':get(r'- d_model: (\d+)'),'n':get(r'- num_layers: (\d+)'),'h':get(r'- num_heads: (\d+)'),'ff':get(r'- d_ff: (\d+)'),'opt':get(r'- Optimizer: ([^\n]+)'),'lr':get(r'- Learning rate: ([^\n]+)'),'wd':get(r'- Weight decay: ([^\n]+)'),'betas':get(r'- Betas: ([^\n]+)')})
 for i,a in enumerate(cs):
  for b in cs[i+1:]:
   diff=[k for k in ['d','n','h','ff','opt','lr','wd','betas'] if a[k]!=b[k]]
   if len(diff)==1 and diff[0] in ['h','ff']:
    k=diff[0];lo,hi=sorted([a,b],key=lambda x:int(x[k])); ans=re.findall(r'[A-E]',r['answer'])
